import { ScatterDimensionOperation } from './../../../sheet-js/src/sheet/operation/type';
import {
  BaseSheet,
  InsertColOperation,
  InsertRowOperation,
  Operation,
  RemoveColOperation,
  RemoveRowOperation,
  Sheet,
  UpdateCellOperation,
  UpdateDimensionOperation,
} from '@bzl/sheet-js';
import { initialDoc } from '../utils';
import { SheetOTType } from '../../src';
import { describe, expect, beforeEach, test, afterEach } from 'vitest';

const examples = [
  {
    type: 'row',
    op: {
      type: 'update-dimension',
      meta: {
        size: 208,
      },
      section: {
        from: 7,
        to: 7,
        isRow: true,
      },
      id: '1',
    } as UpdateDimensionOperation,
  },
  {
    type: 'col',
    op: {
      type: 'update-dimension',
      meta: {
        size: 208,
      },
      section: {
        from: 7,
        to: 7,
        isRow: false,
      },
      id: '1',
    } as UpdateDimensionOperation,
  },
];

describe.each(examples)('left side to update-dimension ($type), right side to:', ({ op }) => {
  let doc1: Omit<BaseSheet, 'apply'>;
  let doc2: Omit<BaseSheet, 'apply'>;
  const op1: UpdateDimensionOperation = op;
  let op2: Operation;

  beforeEach(() => {
    doc1 = initialDoc() as Sheet;
    doc2 = initialDoc() as Sheet;
  });

  afterEach(() => {
    const [op12, op21] = SheetOTType.xTransformMxN([op1], [op2], 'left');
    console.log('op12,', JSON.stringify(op12));
    console.log('op21,', JSON.stringify(op21));

    doc1 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op1) as BaseSheet, op21);
    doc2 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op2) as BaseSheet, op12);
    console.log('doc1,', JSON.stringify(doc1));
    console.log('doc2,', JSON.stringify(doc2));
    expect(doc1).toEqual(doc2);
  });

  describe('scatter-dimension', () => {
    test('row (intersection)', () => {
      op2 = {
        type: 'scatter-dimension',
        id: '1',
        rows: [
          {
            index: op1.section.from,
            meta: {
              size: 100,
            },
          },
          {
            index: op1.section.from + 1,
            meta: {
              size: 100,
              hidden: true,
            },
          },
        ],
        cols: [],
      } as ScatterDimensionOperation;
    });
    test('row (not intersection)', () => {
      op2 = {
        type: 'scatter-dimension',
        id: '1',
        rows: [
          {
            index: op1.section.from - 1,
            meta: {
              size: 100,
            },
          },
        ],
        cols: [],
      } as ScatterDimensionOperation;
    });

    test('col (intersection)', () => {
      op2 = {
        type: 'scatter-dimension',
        id: '1',
        rows: [],
        cols: [
          {
            index: op1.section.from,
            meta: {
              size: 100,
            },
          },
          {
            index: op1.section.from + 1,
            meta: {
              size: 100,
              hidden: true,
            },
          },
        ],
      } as ScatterDimensionOperation;

      test('col (not intersection)', () => {
        op2 = {
          type: 'scatter-dimension',
          id: '1',
          rows: [],
          cols: [
            {
              index: op1.section.from - 1,
              meta: {
                size: 100,
              },
            },
          ],
        } as ScatterDimensionOperation;
      });
    });
  });
  describe.each([{ isRow: false }, { isRow: true }])('update-dimension', ({ isRow }) => {
    test(`at same (${isRow ? 'row' : 'col'})`, () => {
      op2 = {
        type: 'update-dimension',
        meta: {
          size: 500,
        },
        section: {
          from: 7,
          to: 7,
          isRow,
        },
        id: '1',
      } as UpdateDimensionOperation;
    });
    test(`not same (${isRow ? 'row' : 'col'})`, () => {
      op2 = {
        type: 'update-dimension',
        meta: {
          size: 500,
        },
        section: {
          from: 8,
          to: 8,
          isRow,
        },
        id: '1',
      } as UpdateDimensionOperation;
    });
  });

  describe('update-cell', () => {
    test('at before', () => {
      op2 = {
        type: 'update-cell',
        at: [0, op1.section.from - 1],
        newV: null,
        oldV: {
          value: 2,
        },
        id: '1',
      } as UpdateCellOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'update-cell',
        at: [0, op1.section.to + 1],
        newV: null,
        oldV: {
          value: 2,
        },
        id: '1',
      } as UpdateCellOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'update-cell',
        at: [0, op1.section.from],
        newV: null,
        oldV: {
          value: 2,
        },
        id: '1',
      } as UpdateCellOperation;
    });
  });

  describe('insert-col', () => {
    test('at before', () => {
      op2 = {
        type: 'insert-col',
        at: op1.section.from - 1,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'insert-col',
        at: op1.section.to + 1,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'insert-col',
        at: op1.section.from,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
  });

  describe('insert-row', () => {
    test('at before', () => {
      op2 = {
        type: 'insert-row',
        at: op1.section.from - 1,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'insert-row',
        at: op1.section.to + 1,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'insert-row',
        at: op1.section.from,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
  });

  describe('remove-col', () => {
    test('at before', () => {
      op2 = {
        type: 'remove-col',
        at: op1.section.from - 3,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'remove-col',
        at: op1.section.to + 1,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test('intersection before', () => {
      op2 = {
        type: 'remove-col',
        at: op1.section.from - 1,
        count: 3,
        id: '1',
      } as RemoveColOperation;
    });
    test('intersection after', () => {
      op2 = {
        type: 'remove-col',
        at: op1.section.to - 2,
        count: 4,
        id: '1',
      } as RemoveColOperation;
    });
    test('cover', () => {
      op2 = {
        type: 'remove-col',
        at: op1.section.from - 1,
        count: op1.section.to + 1,
        id: '1',
      } as RemoveColOperation;
    });
    test('contain', () => {
      op2 = {
        type: 'remove-col',
        at: op1.section.from,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
  });

  describe('remove-row', () => {
    test('at before', () => {
      op2 = {
        type: 'remove-row',
        at: op1.section.from - 3,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'remove-row',
        at: op1.section.to + 1,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test.only('intersection before', () => {
      op2 = {
        type: 'remove-row',
        at: op1.section.from - 1,
        count: 3,
        id: '1',
      } as RemoveRowOperation;
    });
    test('intersection after', () => {
      op2 = {
        type: 'remove-row',
        at: op1.section.to - 2,
        count: 4,
        id: '1',
      } as RemoveRowOperation;
    });
    test('cover', () => {
      op2 = {
        type: 'remove-row',
        at: op1.section.from - 1,
        count: op1.section.to + 1,
        id: '1',
      } as RemoveRowOperation;
    });
    test('contain', () => {
      op2 = {
        type: 'remove-row',
        at: op1.section.from,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
  });
});
